-- compatibility: incremental
CREATE TABLE review_authority_snapshots(subject_kind TEXT NOT NULL CHECK(subject_kind IN('draft','manual','periodic')),subject_id TEXT NOT NULL,reviewed_version INTEGER NOT NULL,book_id TEXT NOT NULL REFERENCES books(id),firm_id TEXT NOT NULL REFERENCES firms(id),reviewer_user_id TEXT NOT NULL REFERENCES users(id),role_snapshot TEXT NOT NULL CHECK(role_snapshot IN('owner','admin','reviewer')),proof_kind TEXT NOT NULL CHECK(proof_kind IN('review_time','cutover_current_membership')),recorded_at TEXT NOT NULL,PRIMARY KEY(subject_kind,subject_id,reviewed_version));
INSERT INTO review_authority_snapshots SELECT 'draft',r.draft_id,r.reviewed_version,r.book_id,b.firm_id,r.reviewer_user_id,m.role,'cutover_current_membership',CAST(CURRENT_TIMESTAMP AS TEXT) FROM draft_review_receipts r JOIN books b ON b.id=r.book_id JOIN memberships m ON m.firm_id=b.firm_id AND m.user_id=r.reviewer_user_id WHERE m.role IN('owner','admin','reviewer');
INSERT INTO review_authority_snapshots SELECT 'manual',r.id,r.version,r.book_id,b.firm_id,r.reviewed_by,m.role,'cutover_current_membership',CAST(CURRENT_TIMESTAMP AS TEXT) FROM manual_review_requests r JOIN books b ON b.id=r.book_id JOIN memberships m ON m.firm_id=b.firm_id AND m.user_id=r.reviewed_by WHERE r.status='approved' AND m.role IN('owner','admin','reviewer');
INSERT INTO review_authority_snapshots SELECT 'periodic',r.id,r.version,r.book_id,b.firm_id,r.approved_by,m.role,'cutover_current_membership',CAST(CURRENT_TIMESTAMP AS TEXT) FROM periodic_drafts r JOIN books b ON b.id=r.book_id JOIN memberships m ON m.firm_id=b.firm_id AND m.user_id=r.approved_by WHERE r.status IN('approved','posted') AND m.role IN('owner','admin','reviewer');
CREATE TRIGGER record_firm_authority_draft AFTER INSERT ON draft_review_receipts WHEN 1 BEGIN INSERT INTO review_authority_snapshots SELECT 'draft',NEW.draft_id,NEW.reviewed_version,b.id,b.firm_id,NEW.reviewer_user_id,m.role,'review_time',CURRENT_TIMESTAMP FROM books b JOIN memberships m ON m.firm_id=b.firm_id AND m.user_id=NEW.reviewer_user_id WHERE b.id=NEW.book_id AND m.role IN('owner','admin','reviewer'); END;
CREATE TRIGGER record_firm_authority_manual AFTER UPDATE ON manual_review_requests WHEN NEW.status='approved' AND OLD.status<>'approved' BEGIN INSERT INTO review_authority_snapshots SELECT 'manual',NEW.id,NEW.version,b.id,b.firm_id,NEW.reviewed_by,m.role,'review_time',CURRENT_TIMESTAMP FROM books b JOIN memberships m ON m.firm_id=b.firm_id AND m.user_id=NEW.reviewed_by WHERE b.id=NEW.book_id AND m.role IN('owner','admin','reviewer'); END;
CREATE TRIGGER record_firm_authority_periodic AFTER UPDATE ON periodic_drafts WHEN NEW.status='approved' AND OLD.status<>'approved' BEGIN INSERT INTO review_authority_snapshots SELECT 'periodic',NEW.id,NEW.version,b.id,b.firm_id,NEW.approved_by,m.role,'review_time',CURRENT_TIMESTAMP FROM books b JOIN memberships m ON m.firm_id=b.firm_id AND m.user_id=NEW.approved_by WHERE b.id=NEW.book_id AND m.role IN('owner','admin','reviewer'); END;
CREATE TRIGGER authority_identity BEFORE INSERT ON review_authority_snapshots BEGIN
 SELECT CASE WHEN NEW.proof_kind<>'review_time' OR NEW.firm_id IS NOT accounting_actor_firm() OR NEW.reviewer_user_id IS NOT accounting_actor_user() OR NOT EXISTS(SELECT 1 FROM service_book_user_permissions WHERE book_id=NEW.book_id AND user_id=NEW.reviewer_user_id AND can_review) THEN RAISE(ABORT,'Firm review authority required') END;
END;
CREATE TRIGGER require_firm_authority_export BEFORE UPDATE ON drafts WHEN OLD.status='approved' AND NEW.status='exported' AND NOT EXISTS(SELECT 1 FROM review_authority_snapshots WHERE subject_kind='draft' AND subject_id=NEW.id AND reviewed_version=OLD.version-1 AND book_id=NEW.book_id) BEGIN SELECT RAISE(ABORT,'Historical review requires firm verification'); END;
CREATE TRIGGER require_firm_authority_voucher BEFORE INSERT ON vouchers WHEN NOT EXISTS(SELECT 1 FROM review_authority_snapshots s WHERE s.book_id=NEW.book_id AND (s.subject_kind='draft' AND NEW.source_kind='draft' AND NEW.periodic_review_id IS NULL AND s.subject_id=NEW.source_id AND s.reviewed_version=(SELECT CASE WHEN d.status='exported' THEN d.version-2 ELSE d.version-1 END FROM drafts d WHERE d.id=NEW.source_id) OR s.subject_kind='manual' AND s.subject_id=NEW.review_request_id AND s.reviewed_version=(SELECT version FROM manual_review_requests WHERE id=NEW.review_request_id) OR s.subject_kind='periodic' AND s.subject_id=NEW.periodic_review_id AND s.reviewed_version=(SELECT version FROM periodic_drafts WHERE id=NEW.periodic_review_id))) BEGIN SELECT RAISE(ABORT,'Firm review proof required'); END;
CREATE TRIGGER authority_no_update BEFORE UPDATE ON review_authority_snapshots BEGIN SELECT RAISE(ABORT,'Review authority is append-only'); END;
CREATE TRIGGER authority_no_delete BEFORE DELETE ON review_authority_snapshots BEGIN SELECT RAISE(ABORT,'Review authority is append-only'); END;
